\[ \text{Total number of possible parathesisation = }\frac{\binom{2n}{n}}{n + 1} \] <pre><code>static int memo(int[] dim, int i, int j, int[][] dp) {
        if (i == j) return 0;

        if (dp[i][j] != -1) return dp[i][j];

        int cost = Integer.MAX_VALUE;
        for (int k = i; k &lt; j; k++) {
            int currentCost = memo(dim, i, k, dp)
                + memo(dim, k + 1, j, dp)
                + dim[i - 1] * dim[k] * dim[j];

            cost = Math.min(cost, currentCost);
        }

        return dp[i][j] = cost;
    }

    static int tabulation(int[] dim) {
        int n = dim.length;

        int[][] dp = new int[n][n];

        for (int L = 2; L &lt; n; L++) {
            for (int i = 1; i &lt; n - L + 1; i++) {
                int j = i + L - 1;

                dp[i][j] = Integer.MAX_VALUE;

                for (int k = i; k &lt; j; k++) {
                    dp[i][j] = Math.min(
                        dp[i][j], 
                        dp[i][k] + dp[k + 1][j] + dim[i - 1] * dim[k] * dim[j]
                    );
                }
            }
        }

        return dp[1][n - 1];
    }

    static int matrixMultiplication(int arr[]) {
        // code here
        int n = arr.length;
        int[][] dp = new int[n][n];

        for (int[] row : dp) {
            Arrays.fill(row, -1);
        }

        return tabulation(arr);
